import{_ as e,o,c as a,ag as n}from"./chunks/framework.qXLDknWC.js";const g=JSON.parse('{"title":"AI Context Panel","description":"","frontmatter":{},"headers":[],"relativePath":"features/ai-context.md","filePath":"features/ai-context.md"}'),r={name:"features/ai-context.md"};function i(s,t,l,c,h,d){return o(),a("div",null,[...t[0]||(t[0]=[n('<h1 id="ai-context-panel" tabindex="-1">AI Context Panel <a class="header-anchor" href="#ai-context-panel" aria-label="Permalink to &quot;AI Context Panel&quot;">​</a></h1><p>The <strong>AI Context</strong> panel is a docked side panel that lets you control what gets sent to AI-powered features. That includes:</p><ul><li><strong>Character card sections</strong> you pin (Description, Personality, Scenario, and so on)</li><li>Optional <strong>custom context</strong> — free-text notes you paste for this character</li></ul><p>Both feed the <strong>Orion</strong> chat assistant and the <strong>AI toolbar</strong> (Enhance, Rephrase, Shorten, lorebook key generation, and similar ops). Think of the panel as choosing what the AI &quot;sees&quot; when it helps you write or edit.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>This panel works with your configured AI provider. If you haven&#39;t set one up yet, see <a href="/CharacterVault/docs/configuration/ai-setup">AI Setup</a>.</p></div><h2 id="opening-the-panel" tabindex="-1">Opening the Panel <a class="header-anchor" href="#opening-the-panel" aria-label="Permalink to &quot;Opening the Panel&quot;">​</a></h2><p>The panel lives on the left side of the workspace. Click the <strong>AI Context</strong> button in the workspace header to open or close it. On mobile, it appears as a full-screen overlay with a close button.</p><h2 id="how-it-works" tabindex="-1">How It Works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How It Works&quot;">​</a></h2><p>From top to bottom the panel shows:</p><ol><li><strong>Usage</strong> — estimated tokens for everything currently included (pinned sections + custom context when enabled), against your sampler context length.</li><li><strong>Custom</strong> — optional free-text block for this character (see <a href="#custom-context">Custom Context</a>).</li><li><strong>Selected</strong> — chips for card sections currently pinned; <strong>Clear all</strong> removes section pins only.</li><li><strong>Section list</strong> — searchable checklist of eligible card sections. Toggle a row to pin or unpin it.</li></ol><h3 id="available-sections" tabindex="-1">Available Sections <a class="header-anchor" href="#available-sections" aria-label="Permalink to &quot;Available Sections&quot;">​</a></h3><p>Not every character field appears in the context panel. These sections are excluded:</p><ul><li>Image (base64 data)</li><li>Extensions</li><li>Avatar URL</li><li>Character version</li><li>Tags</li></ul><p>The lorebook appears in the list only if your character actually has lorebook entries.</p><h2 id="custom-context" tabindex="-1">Custom Context <a class="header-anchor" href="#custom-context" aria-label="Permalink to &quot;Custom Context&quot;">​</a></h2><p><strong>Custom context</strong> is a single free-text block you can paste or type for the <strong>currently open character</strong>. Use it for notes that are not (or not yet) part of the card: world facts, style guides, reference dumps, WIP outlines, or anything else you want Orion and the toolbar to see.</p><h3 id="adding-and-editing" tabindex="-1">Adding and editing <a class="header-anchor" href="#adding-and-editing" aria-label="Permalink to &quot;Adding and editing&quot;">​</a></h3><ol><li>Open the <strong>AI Context</strong> panel.</li><li>Under <strong>Custom</strong>, click <strong>Add custom context…</strong> (or the pencil if you already have text).</li><li>In the modal, paste or type your notes.</li><li>Leave <strong>Include in AI context when enabled</strong> checked if you want it used on the next request.</li><li>Click <strong>Save</strong>.</li></ol><p>The modal shows a live token estimate and soft warnings when the block is large relative to your context window. Large pastes are allowed; the AI request layer still trims content when the total input exceeds the window.</p><h3 id="enabling-and-removing" tabindex="-1">Enabling and removing <a class="header-anchor" href="#enabling-and-removing" aria-label="Permalink to &quot;Enabling and removing&quot;">​</a></h3><ul><li><strong>Checkbox</strong> on the Custom row — include or exclude the saved text without deleting it.</li><li><strong>Remove</strong> — deletes the custom context for this character (confirm first).</li><li>Empty save (clear the textarea and save) also clears storage for that character.</li></ul><h3 id="what-uses-custom-context" tabindex="-1">What uses custom context? <a class="header-anchor" href="#what-uses-custom-context" aria-label="Permalink to &quot;What uses custom context?&quot;">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Surface</th><th style="text-align:left;">Uses custom context when enabled?</th></tr></thead><tbody><tr><td style="text-align:left;">Orion (Ask AI) chat</td><td style="text-align:left;">Yes</td></tr><tr><td style="text-align:left;">AI toolbar (Enhance, Rephrase, Custom, etc.)</td><td style="text-align:left;">Yes</td></tr><tr><td style="text-align:left;">Lorebook ✨ key generation</td><td style="text-align:left;">Yes (same context pipeline as the toolbar)</td></tr><tr><td style="text-align:left;">AI Creation Studio</td><td style="text-align:left;">No (studio has its own flow)</td></tr></tbody></table><p>Custom context is appended <strong>after</strong> pinned card sections when building a request, so core card fields take priority if the context window is tight.</p><h3 id="storage-and-privacy" tabindex="-1">Storage and privacy <a class="header-anchor" href="#storage-and-privacy" aria-label="Permalink to &quot;Storage and privacy&quot;">​</a></h3><ul><li>Stored <strong>only in this browser</strong> (IndexedDB), <strong>per character</strong>.</li><li><strong>Not</strong> written into the character card <code>spec</code>, <strong>not</strong> included in PNG/JSON export, and <strong>not</strong> part of SillyTavern-compatible card data.</li><li><strong>Not</strong> included in snapshots/history of the card.</li><li>Duplicating a character <strong>copies</strong> its custom context to the new card.</li><li>Deleting a character removes its custom context with it.</li><li>Switching characters does not leave the previous character&#39;s text in the open editor; the full body is loaded only when you open the modal or when an AI request needs it.</li></ul><div class="warning custom-block"><p class="custom-block-title">Export and backup</p><p>Vault <strong>Backup</strong> / card export does <strong>not</strong> include custom context. If you rely on those notes, keep a separate copy or re-paste after moving machines. See <a href="/CharacterVault/docs/privacy">Privacy</a> for how local storage works.</p></div><h2 id="token-estimation" tabindex="-1">Token Estimation <a class="header-anchor" href="#token-estimation" aria-label="Permalink to &quot;Token Estimation&quot;">​</a></h2><p>The panel shows an estimated token count for pinned sections and, when enabled, custom context. It uses a simple formula: text size in bytes divided by 4 (rounded up). This is an approximation — actual token counts vary by model.</p><p>The usage bar changes color as you approach the limit:</p><ul><li>Green — under 50% of context limit</li><li>Yellow — between 50% and 80%</li><li>Red — over 80% (shows an over-limit warning)</li></ul><p>The context limit comes from your current sampler settings (<strong>Settings → Sampler → Context Length</strong>).</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>The token count shown here is an estimate. Different models tokenize text differently, so your actual usage may be higher or lower. Treat the percentage as a rough guide rather than an exact number.</p></div><h2 id="lorebook-in-context" tabindex="-1">Lorebook in Context <a class="header-anchor" href="#lorebook-in-context" aria-label="Permalink to &quot;Lorebook in Context&quot;">​</a></h2><p>Using the lorebook with the AI Context panel works in two steps:</p><ol><li><strong>Add Lorebook to context</strong> — In the Add Context section, click &quot;Lorebook&quot; to include it. Without this, no lorebook entries will be included regardless of their individual settings.</li></ol><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>If you don&#39;t see &quot;Lorebook&quot; in the Add Context list, it means your character doesn&#39;t have any lorebook entries yet.</p></div><ol start="2"><li><strong>Choose which entries</strong> — Once the lorebook is in context, open the lorebook editor. Each entry has an eye icon that controls whether it gets included: <ul><li>Eye open — entry content is sent to Orion and the AI toolbar</li><li>Eye closed — entry is excluded from AI context</li></ul></li></ol><p>This two-layer system means you can include the entire lorebook but hide specific entries by closing their eye icons. Or keep the lorebook out of AI context entirely while leaving all entries enabled for roleplay in SillyTavern.</p><p>The lorebook editor also shows an <strong>AI context</strong> usage bar (included entry count and estimated tokens vs book budget or sampler context length), with <strong>All</strong> / <strong>None</strong> shortcuts.</p><h3 id="how-the-toggles-work-together" tabindex="-1">How the Toggles Work Together <a class="header-anchor" href="#how-the-toggles-work-together" aria-label="Permalink to &quot;How the Toggles Work Together&quot;">​</a></h3><p>Each lorebook entry has two independent settings:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Toggle</th><th style="text-align:left;">Used By</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Enabled</strong> (main toggle)</td><td style="text-align:left;">SillyTavern and other chat interfaces during roleplay</td></tr><tr><td style="text-align:left;"><strong>Context</strong> (eye icon)</td><td style="text-align:left;">Orion and AI toolbar operations</td></tr></tbody></table><p>You might disable certain entries for Orion and the AI toolbar because they&#39;re too long, irrelevant to editing, or you&#39;d rather the AI not see them. Meanwhile, those same entries stay enabled for actual roleplay. The settings don&#39;t affect each other.</p><h3 id="linked-library-books" tabindex="-1">Linked library books <a class="header-anchor" href="#linked-library-books" aria-label="Permalink to &quot;Linked library books&quot;">​</a></h3><p>You can <strong>link</strong> a book from the <a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a> to a character. Linked books stay in sync with the lorebook on the card, so Orion and the AI toolbar see the same entries you would export. Entry-level context eyes still apply as above.</p><p>See <a href="/CharacterVault/docs/features/lorebook-vault#attach-to-a-character-vault-local">Lorebook Vault → Linking</a>.</p><h2 id="next-steps" tabindex="-1">Next Steps <a class="header-anchor" href="#next-steps" aria-label="Permalink to &quot;Next Steps&quot;">​</a></h2><ul><li><a href="/CharacterVault/docs/features/lorebook-editor">Lorebook Editor</a></li><li><a href="/CharacterVault/docs/features/lorebook-vault">Lorebook Vault</a></li><li><a href="/CharacterVault/docs/features/editor">Editor &amp; AI Toolkit</a> (AI toolbar operations)</li><li><a href="/CharacterVault/docs/features/ai-assistant">AI Assistant (Orion)</a></li><li><a href="/CharacterVault/docs/configuration/ai-setup">Configure AI provider</a></li></ul>',49)])])}const p=e(r,[["render",i]]);export{g as __pageData,p as default};
